//! Compare 91FBE0 scripted factory projection to retained native rows.
use spore_core::cell_provider_factory_validate_v1::{project,Action};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let p=std::env::args().nth(1).expect("native stdout");let b=std::fs::read(p).unwrap();assert_eq!(b.len(),144);for i in 0..6{let k=i%3;let cw=if i>=3{0x37f}else{0x27f};let candidate=if k==0{None}else{Some(1)};let validation=match k{0=>None,1=>Some(Some(2)),_=>Some(None)};let x=project(0x12345678,0x0179c807,0,0,candidate,validation,cw,0x1f80,true).unwrap();let row=&b[i*24..(i+1)*24];assert_eq!(w(row,0),u32::from(x.result.is_some()));assert_eq!(w(row,4),1);assert_eq!(w(row,8),u32::from(candidate.is_some()));assert_eq!(w(row,12),if x.actions.contains(&Action::ReleaseSecond(1)){3}else{0});let fp=w(row,16);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,20)&!0x3f,0x1f80);}println!("matched 6 retained factory validation rows; callbacks scripted");}
